import React, { useEffect, useState } from 'react';
import {
  Modal, Box, Typography, IconButton, TextField, Button, Divider
} from '@mui/material';
import CloseIcon from '@mui/icons-material/Close';
import CommentBox from '../Shared/CommentBox/index.tsx';
import { CampaignListActions } from '../../Services/_actions';
import { useSnackBar } from '../FlowBuilder/Common/SnackBar/index.tsx';

export interface Comment {
  user_name: string;
  timestamp: string; // ISO string
  comment: string;
}

interface ViewCommentModalProps {
  open: boolean;
  onClose: () => void;
  campaign: any;
}

const ViewCommentModal: React.FC<ViewCommentModalProps> = ({
  open,
  onClose,
  campaign
}) => {
  const actions = CampaignListActions();
  const [commentList, setCommentList] = useState<any>([]);
  const { showSnackBar } = useSnackBar();

  const getComments = async () => {
    try {
      if (campaign && campaign.proposal_id) {
        const response = await actions.getCampaignComments(campaign.proposal_id, 'CAMPAIGN');

        if (response && response.status === 200) {
          const generalComments = response.data?.null?.general || [];
          setCommentList([...generalComments]);
        } else {
          showSnackBar("Error occurred while fetching comments", "error");
        }
      }
    } catch (error) {
      showSnackBar(error?.toString() || "Error", "error");
    }
  };


  useEffect(() => {
    getComments()
  }, [campaign])

  return (
    <Modal open={open} onClose={onClose}>
      <Box sx={{
        position: 'absolute',
        top: '50%',
        left: '50%',
        transform: 'translate(-50%, -50%)',
        bgcolor: 'background.paper',
        boxShadow: 24,
        borderRadius: 2,
        p: 4,
        width: 600,
        maxHeight: '90vh',
        overflowY: 'auto',
      }}>
        <Box display="flex" justifyContent="space-between" alignItems="center" mb={2}>
          <Typography variant="h6" fontWeight="bold">
            View Comments For {campaign?.name || ''}
          </Typography>
          <IconButton onClick={onClose}><CloseIcon /></IconButton>
        </Box>
        <CommentBox commentList={commentList || []} onSubmitComment={(comment) => { console.log(comment) }} />
      </Box>
    </Modal>
  );
};

export default ViewCommentModal;
